function setZoom(z,pivot={x:viewport.clientWidth/2,y:viewport.clientHeight/2}){const next=Math.max(.08,Math.min(4,z)),wx=(pivot.x-camera.x)/camera.z,wy=(pivot.y-camera.y)/camera.z;camera={x:pivot.x-wx*next,y:pivot.y-wy*next,z:next};renderScene()}
