function positions(){const b=board.bounds,w=viewport.clientWidth,h=viewport.clientHeight,cx=camera.x+(b.x+b.w/2)*camera.z,cy=camera.y+(b.y+b.h/2)*camera.z;const pos={top:[cx,camera.y+b.y*camera.z],bottom:[cx,camera.y+(b.y+b.h)*camera.z],left:[camera.x+b.x*camera.z,cy],right:[camera.x+(b.x+b.w)*camera.z,cy]};document.querySelectorAll('[data-expand]').forEach(el=>{const [x,y]=pos[el.dataset.expand];el.style.left=Math.max(86,Math.min(w-24,x))+'px';el.style.top=Math.max(49,Math.min(h-95,y))+'px'});$('canvas-label').style.left=Math.max(20,Math.min(w-130,camera.x+b.x*camera.z))+'px';$('canvas-label').style.top=Math.max(17,Math.min(h-120,camera.y+b.y*camera.z-24))+'px';}
function lineMarkup(start,end,color,stroke,marker='tip',hit=false){return `<defs><marker id="${marker}" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="11" markerHeight="11" orient="auto" markerUnits="userSpaceOnUse"><path d="M2 2l8 4-8 4" fill="none" stroke="${escape(color)}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></marker></defs><line x1="${start.x}" y1="${start.y}" x2="${end.x}" y2="${end.y}" stroke="${escape(color)}" stroke-width="${stroke}" marker-end="url(#${marker})"/>${hit?`<line class="vector-hit" x1="${start.x}" y1="${start.y}" x2="${end.x}" y2="${end.y}" stroke="transparent" stroke-width="${Math.max(14,14/camera.z)}"/>`:''}`;}
