document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelection();return}if(e.code==='Space'){e.preventDefault();space=true;viewport.classList.add('space-pan');return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();return}if(e.key==='Escape'){if(gesture?.before)board=gesture.before;gesture=null;viewport.classList.remove('panning');arrowStart=null;selected=null;setTool('select');return}if(e.shiftKey&&e.code==='Digit1'){e.preventDefault();fit();return}if(mod||e.altKey)return;const tools={v:'select',h:'hand',t:'text',a:'arrow',p:'pen'};if(tools[e.key.toLowerCase()]){selected=null;setTool(tools[e.key.toLowerCase()])}if(e.key.toLowerCase()==='i'&&available())$('image-input').click();const o=find(selected);if(o&&editable(board,o)&&o.type!=='arrow'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();mutate(()=>{const step=e.shiftKey?10:1;o.x+=(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0);o.y+=(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0);contain(board,o)})}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;viewport.classList.remove('space-pan')}});window.addEventListener('blur',()=>{space=false;viewport.classList.remove('space-pan','panning');if(gesture?.before)board=gesture.before;gesture=null;render()});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='s'){selected=null;setTool('shape');}});
$('inspector').addEventListener('click',e=>{const route=e.target.closest('[data-arrow-route]'),action=e.target.closest('[data-arrow-curve-action]')?.dataset.arrowCurveAction;if(route){curvePointArrow=null;viewport.classList.remove('adding-curve-point')}if(!action)return;const object=find(selected);if(object?.type!=='arrow'||!editable(board,object))return;if(action==='add'){setTool('select');selected=object.id;curvePointArrow=object.id;viewport.classList.add('adding-curve-point');render();$('hint').textContent='Click the canvas to place a curve point · Esc to cancel';notify('Click anywhere on the canvas to bend this arrow there.')}if(action==='clear'){curvePointArrow=null;viewport.classList.remove('adding-curve-point');mutate(()=>object.controlPoints=[]);}});
function enhanceArrowInspector(){const object=find(selected),target=object?.type==='arrow'?object:!object&&tool==='arrow'?defaults:null;if(!target)return;const grid=$('inspector').querySelector('.arrow-route-grid');if(!grid)return;const disabled=object&&!editable(board,object)?'disabled':'';grid.insertAdjacentHTML('beforeend',`<button data-arrow-route="smartCurve" class="smart-curve-option ${(target.route||'straight')==='smartCurve'?'chosen':''}" aria-pressed="${(target.route||'straight')==='smartCurve'}" ${disabled}>Smart curve</button>`);if(object){const count=object.controlPoints?.length||0;grid.insertAdjacentHTML('afterend',`<div class="curve-editor"><div><b>Curve points</b><span>${count||'None'}</span></div><div><button data-arrow-curve-action="add" ${disabled}>+ Add point</button><button data-arrow-curve-action="clear" ${!count||disabled?'disabled':''}>Clear</button></div><p>Place points on the canvas, drag the numbered handles to refine the path, or double-click a handle to remove it.</p></div>`);}}
const baseSetTool=setTool,baseRenderInspector=renderInspector;
setTool=function(value){curvePointArrow=null;viewport.classList.remove('adding-curve-point');baseSetTool(value);};
renderInspector=function(){baseRenderInspector();enhanceArrowInspector();};
if(innerWidth<650){document.body.classList.add('sidebar-closed');$('layers-toggle').setAttribute('aria-expanded','false')}
new ResizeObserver(()=>{const size={w:viewport.clientWidth,h:viewport.clientHeight};if(!lastSize)fit();else{camera.x+=(size.w-lastSize.w)/2;camera.y+=(size.h-lastSize.h)/2;renderScene()}lastSize=size}).observe(viewport);
viewport.dataset.tool='select';render();
// Optional agent tools share the exact same board actions as the visible editor.
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const tools=[
 {name:'read_board',description:'Read canvas bounds, layers, and objects on this board.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({bounds:{...board.bounds},layers:clone(board.layers),objects:board.objects.map(o=>({...o,src:undefined}))})},
 {name:'add_texts',description:'Add one or more text objects to the active visible, unlocked layer.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:30,items:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:5000},x:{type:'number',minimum:-1000000,maximum:1000000},y:{type:'number',minimum:-1000000,maximum:1000000}},required:['text','x','y'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.items)||!input.items.length||input.items.length>30||input.items.some(i=>!i||typeof i.text!=='string'||!i.text.trim()||i.text.length>5000||![i.x,i.y].every(n=>Number.isFinite(n)&&Math.abs(n)<=1000000)))throw new Error('Provide 1–30 texts with valid coordinates.');if(!available())throw new Error('The active layer is unavailable.');const ids=[];mutate(()=>{for(const i of input.items)ids.push(addObject(board,{type:'text',text:i.text,x:i.x,y:i.y,w:280,h:50,fontSize:defaults.fontSize,bold:defaults.bold,color:defaults.color}).id)});return {ids};}},
 {name:'expand_canvas',description:'Add a strip of canvas in the specified direction.',inputSchema:{type:'object',properties:{direction:{type:'string',enum:['top','right','bottom','left']}},required:['direction'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['top','right','bottom','left'].includes(input.direction))throw new Error('Provide a valid direction.');expandDirection(input.direction);return {bounds:{...board.bounds}};}},
 {name:'connect_objects',description:'Create an arrow between two different visible, unlocked objects.',inputSchema:{type:'object',properties:{startId:{type:'string'},endId:{type:'string'}},required:['startId','endId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{const a=find(input?.startId),b=find(input?.endId);if(!a||!b||a.id===b.id||a.type==='arrow'||b.type==='arrow'||!editable(board,a)||!editable(board,b)||!available())throw new Error('Provide two different available object IDs.');let id;mutate(()=>id=connect(board,a.id,b.id,{color:defaults.color,stroke:defaults.stroke}).id);return {id};}}
 ];for(const entry of tools){try{Promise.resolve(context.registerTool(entry,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
